import{z as o,x as s,o as B,c as i,q as e,j as r,D as a,d as l,s as t,S as n}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"调度器的框架对照","description":"","frontmatter":{"title":"调度器的框架对照","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-scheduler-comparison.md","filePath":"llm/fw-scheduler-comparison.md","lastUpdated":1791063341000}'),p={name:"llm/fw-scheduler-comparison.md"};function d(m,E,h,D,c,C){const A=s("Mermaid");return B(),i("div",null,[E[2]||(E[2]=e('<h1 id="调度器的框架对照" tabindex="-1">调度器的框架对照 <a class="header-anchor" href="#调度器的框架对照" aria-label="Permalink to &quot;调度器的框架对照&quot;">​</a></h1><div class="epigraph"><p>六个仓库看完，调度器的问题从来不是「怎么排」，而是它住在哪个进程里、每步吐出什么、丢了算谁的。</p><footer>—— 据 Yu 等，Orca，OSDI 2023；Kwon 等，SOSP 2023；SGLang，NeurIPS 2024 及各仓库源码整理</footer></div><p><a href="/llm/fw-hf-generate-walkthrough">上一课</a>收在「不调度」的基线上，主流框架单元读毕，进入对照单元。机制面已各有一课：指标与双分位、迭代级组批与 token 预算、抢占与迁移、优先级公平，见调度课序的 <a href="/llm/sch-basics-metrics">基础与指标</a>、<a href="/llm/sch-continuous-batching-deep">连续批处理深入</a>、<a href="/llm/sch-preemption-migration">抢占与迁移</a>，vLLM 调度器的细节另见 <a href="/llm/vllm-scheduler">调度器</a>。本课把六个走读对象的调度器并排放，只问三件事：住在哪、每步产出什么、丢了谁负责，以各仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐仓读码时每家的调度器都「看得懂」，并排才显出分歧。同一个 Orca 式迭代级调度，在 vLLM 是核心进程里的单线程类，在 SGLang 是独立进程的事件循环加策略函数，在 TGI 拆到 Rust 路由，在 TensorRT-LLM 沉进 C++ 运行库，在 llama.cpp 退化成槽位表，在 Transformers 干脆不存在。分歧不是品味，是<strong>语言与进程边界</strong>的选择：调度器写在哪一侧，决定了谁能改它、它停了谁死、以及它每步要为跨边界付出什么。</p><h3 id="三问对照" tabindex="-1">三问对照 <a class="header-anchor" href="#三问对照" aria-label="Permalink to &quot;三问对照&quot;">​</a></h3><p>第一问，住在哪。vLLM 的调度器与引擎核心同进程单线程，改动最便宜，审计最直接；SGLang 把它放进独立调度进程，换来组批逻辑不被分词拖累，代价是边界上多一次消息往返；TGI 由 Rust 路由器排队组批，Python 侧只执行，边界横在语言之间；TensorRT-LLM 的批管理器在编译库内部，Python 只是请求应答的壳。第二问，每步产出什么。这是走读过的锚点结构：vLLM 的调度输出是一步指令全集，SGLang 是从调度批到内核批的收窄链，TensorRT-LLM 是运行库内部的批决议，llama.cpp 是槽位拼接的批，Transformers 是调用方给死的张量。第三问，丢了算谁。有显式调度输出与块表的框架能重算恢复——抢占即重算；没有的只能整批重来。</p>',7)),(B(),r(n,null,{default:a(()=>[t(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20A%5B%22vLLM%EF%BC%9A%E6%A0%B8%E5%BF%83%E8%BF%9B%E7%A8%8B%E5%8D%95%E7%BA%BF%E7%A8%8B%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20Q%20--%3E%20B%5B%22SGLang%EF%BC%9A%E7%8B%AC%E7%AB%8B%E8%B0%83%E5%BA%A6%E8%BF%9B%E7%A8%8B%E4%BA%8B%E4%BB%B6%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20Q%20--%3E%20C%5B%22TGI%EF%BC%9ARust%20%E8%B7%AF%E7%94%B1%E7%BB%84%E6%89%B9%22%5D%0A%20%20Q%20--%3E%20D%5B%22TensorRT-LLM%EF%BC%9AC%2B%2B%20%E6%89%B9%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%0A%20%20Q%20--%3E%20E%5B%22llama.cpp%EF%BC%9A%E6%A7%BD%E4%BD%8D%E8%A1%A8%22%5D%0A%20%20Q%20--%3E%20F%5B%22Transformers%EF%BC%9A%E6%97%A0%E8%B0%83%E5%BA%A6%22%5D%0A%20%20A%20--%3E%20O1%5B%22%E8%B0%83%E5%BA%A6%E8%BE%93%E5%87%BA%EF%BC%9A%E4%B8%80%E6%AD%A5%E6%8C%87%E4%BB%A4%E5%85%A8%E9%9B%86%22%5D%0A%20%20B%20--%3E%20O2%5B%22%E8%B0%83%E5%BA%A6%E6%89%B9%E5%88%B0%E5%86%85%E6%A0%B8%E6%89%B9%E6%94%B6%E7%AA%84%E9%93%BE%22%5D%0A%20%20D%20--%3E%20O3%5B%22%E5%BA%93%E5%86%85%E6%89%B9%E5%86%B3%E8%AE%AE%22%5D%0A%20%20E%20--%3E%20O4%5B%22%E6%A7%BD%E4%BD%8D%E6%8B%BC%E6%8E%A5%E6%89%B9%22%5D%0A%20%20F%20--%3E%20O5%5B%22%E8%B0%83%E7%94%A8%E6%96%B9%E5%BC%A0%E9%87%8F%E6%89%B9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">对照时最易张冠李戴的是「优先级」：vLLM 与 SGLang 长期默认先到先服务，排序策略里藏着缓存感知变体；优先级与公平性是调度课序的扩展机制，不能因为某仓库有个参数名带 priority 就认定它实现了加权公平队列。</span></p><p><span class="marginnote">「迭代级调度」翻译成大白话：模型每算完一步（吐出一个 token）就重新组一次批，新请求插队最多等一步、几十毫秒；老的「请求级组批」要等整批全部生成完才放人，长句会拖住短句几十秒。一步之差，就是吞吐与首字延迟的分水岭。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把三问落成读新框架的检查单。读码顺序：先找「一步的产出物」这个类型，它附近就是调度器；再找队列归属的进程，看分词、组批、执行各在哪侧；最后找抢占与恢复的路径，确认「请求丢了算谁」的答案。对照实验则反向操作：固定工作负载与指标口径，只换框架或只换调度参数，观察双分位数的变化——这属于下一单元性能课的方法，此处只立口径。检查单的好处是防背结论：仓库在动，类型名会漂，三问的答案结构比答案本身耐用。</p><p><span class="marginnote">双分位数指 P50 与 P99 两个延迟分位：P50 是「一半请求比这快」，P99 是「最慢的 1% 也要比这快」。调度实验只看均值会被长尾骗——一个被饿着的极端慢请求能把平均值拖高数倍，分位数才能定位到「谁在受苦」。举例：P50 = 200 ms、P99 = 2 s，说明系统对多数人很快，但尾部体验已被调度决策毁掉。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>并排之后，机制上的共性只有一条：<strong>一步的产出物决定一切</strong>。凡有显式步指令集的框架，抢占、重算、统计、流式回放都围着它长；凡没有的，正确性退回调用方。差异则全在边界位置：边界每往外推一层，调度器的自由度小一分、确定性多一分——TensorRT-LLM 把决议封进库里换热路径，vLLM 把调度器亮在最外层换可改性。没有免费的位置，只有与团队、与部署档位相称的位置。这也解释了为何同机制课在六家里长得不一样：机制课教的是不变量，仓库教的是把不变量放在哪个进程里兑现。</p>',7)),(B(),r(n,null,{default:a(()=>[t(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%AF%B7%E6%B1%82%E8%A2%AB%E6%8A%A2%E5%8D%A0%22%5D%20--%3E%20Q%7B%22%E8%B0%83%E5%BA%A6%E8%BE%93%E5%87%BA%E9%87%8C%E6%9C%89%E6%98%BE%E5%BC%8F%E6%AD%A5%E6%8C%87%E4%BB%A4%E9%9B%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9C%89%22%7C%20R%5B%22%E4%BB%8E%E5%9D%97%E8%A1%A8%20%2F%20%E6%AD%A5%E6%8C%87%E4%BB%A4%E9%87%8D%E5%BB%BA%E7%8A%B6%E6%80%81%22%5D%0A%20%20R%20--%3E%20S%5B%22%E9%87%8D%E7%AE%97%E7%BC%BA%E5%A4%B1%E7%9A%84%20KV%EF%BC%8C%E5%9B%9E%E5%88%B0%E9%98%9F%E5%88%97%E7%BB%AD%E5%86%99%22%5D%0A%20%20S%20--%3E%20T%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%E7%85%A7%E5%B8%B8%E7%94%9F%E6%88%90%EF%BC%8C%E6%8D%9F%E5%A4%B1%E4%BB%85%E5%87%A0%E4%B8%AA%20token%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20U%5B%22%E6%97%A0%E7%8A%B6%E6%80%81%E5%8F%AF%E6%9F%A5%22%5D%0A%20%20U%20--%3E%20V%5B%22%E5%8F%AA%E8%83%BD%E6%95%B4%E6%89%B9%E9%87%8D%E6%9D%A5%EF%BC%8C%E5%B7%B2%E7%94%9F%E6%88%90%20token%20%E5%85%A8%E9%83%A8%E4%BD%9C%E5%BA%9F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">初学者容易以为「抢占」是杀掉请求，实际上 vLLM 的抢占只是把部分请求的 KV 块换出或释放，把显存让给更要紧的批；请求本身回到队列，之后按块表重建、从断点续算。这就是第三问「丢了算谁」的答案来源：有块表就有断点，没块表只好从头再来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>以各仓库当时状态为准：SGLang 的重叠调度、vLLM 的多调度器演进、TGI 的维护模式都在变，本课钉的是位置与产出物的类型，不是版本号。多副本、PD 分离、多实例路由属于部署层调度，在调度课序与 SGLang Router 各有专课，本课只对照单实例内部。六个对象也不是全景：商用闭源引擎与端侧系统各有调度答案，方法可迁移，结论不可。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对照的三问：调度器住在哪个进程、每步产出什么、请求丢了算谁。</li><li>一步的产出物是共性锚点：显式步指令集撑起抢占、重算与流式；没有它，正确性退回调用方。</li><li>语言与进程边界决定调度器形态：可改性与确定性沿边界此消彼长。</li><li>读新框架先找产出物类型，再找队列归属，最后找恢复路径；答案结构比类型名耐用。</li><li>部署层调度与单实例内调度分层，不在本课混谈；结论以各仓库当时状态为准。</li><li>出处：Orca（OSDI 2023）、vLLM（SOSP 2023）、SGLang（NeurIPS 2024）与各仓库源码，按对照整理。</li></ul>',5))])}const T=o(p,[["render",d]]);export{L as __pageData,T as default};
